// ─── QUIZ SENARYO ÇEVİRİLERİ (190) ──────────────────────────────────
QUIZ_I18N.ar = {"quiz_d2_senaryo_jury_1": "في جولة واحدة عددتَ للرياضي نفسه بعد السقوط مرّتين. عند الطلب تُبلِغ لجنة التحكيم بحالة العدّ.", "quiz_d2_senaryo_jury_2": "عُدَّ لرياضيٍّ للمرة الثالثة في جولة واحدة. عند الطلب تُبلِغ لجنة التحكيم بحالة العدّ.", "quiz_d2_senaryo_jury_3": "خلال النزال وجّهتَ للركن الأحمر تنبيهين رسميين. عند الطلب تُبلِغ لجنة التحكيم بحالة التنبيهات.", "quiz_d2_senaryo_jury_4": "أثناء فحص القفازات عند مدخل الحلبة تلاحظ أن الرياضي لا يضع لفافات تحت القفازات. تُبلِغ لجنة التحكيم بهذه المخالفة.", "quiz_d2_senaryo_jury_5": "عليك أن تسأل لجنة التحكيم إن كان يُسمح للمدرّب بتبديل واقي رأسٍ معطوب.", "quiz_d2_senaryo_jury_6": "تحتاج إلى شريط لاصق لتثبيت معدّات أحد الرياضيين. تطلب المساعدة من لجنة التحكيم.", "quiz_d2_senaryo_jury_7": "تدخل رياضية إلى الحلبة بحجابٍ أسود. تُبلِغ لجنة التحكيم بذلك فوراً.", "quiz_d2_senaryo_jury_8": "قبل النزال تكتشف أن الرياضي لا يضع واقي العانة. تُبلِغ لجنة التحكيم بذلك فوراً.", "quiz_d2_senaryo_jury_9": "تفحص واقي جسم الرياضي وترى أنه غير معتمد من IFMA. تُبلِغ لجنة التحكيم بأن تبديله إلزامي.", "quiz_d2_senaryo_jury_10": "عليك مغادرة منطقة المنافسة لفترة قصيرة للذهاب إلى الحمّام. تطلب الإذن من لجنة تحكيم البروتوكول.", "quiz_d2_senaryo_jury_11": "عليك الاتصال بشخصٍ هاتفياً. تطلب الإذن من لجنة تحكيم البروتوكول.", "quiz_d2_senaryo_jury_12": "تنبّهك لجنة التحكيم إلى خطأ بسيط في موقعك خلال الجولة الأخيرة. تتقبّل الملاحظة وتقول إنك ستنتبه.", "quiz_d2_senaryo_jury_13": "حسبتَ نتيجةً أو عدّاً بالخطأ فصحّحتك لجنة التحكيم. تعتذر عن خطئك وتؤكّد أنك ستنتبه.", "quiz_d2_senaryo_jury_14": "ترى حكماً آخر يحمل معدّات ثقيلة أو يواجه صعوبة في مهمة عند الطاولة. تعرض عليه مساعدتك.", "quiz_d2_senaryo_jury_15": "قيل لك إن لديك تكليفاً، لكنك لا تتذكّر دورك بدقّة (حكم جانبي أم حكم وسط). تسأل للتوضيح.", "quiz_d2_senaryo_jury_16": "كُلِّفتَ حكماً جانبياً، لكنك لا تتذكّر بدقّة على أي كرسي (1، 2، 3، 4 أو 5) يجب أن تجلس. تسأل عن ذلك.", "quiz_d2_senaryo_jury_17": "تريد الاطّلاع على قائمة التكليف الرسمية لمعرفة مهام الحكّام. تطلب الإذن.", "quiz_d2_senaryo_jury_18": "للتحضير لمهمتك، تريد معرفة فئة النزال القادم.", "quiz_d2_senaryo_jury_19": "عليك التحقّق من ترتيب النزالات لتعرف متى يجب أن تكون جاهزاً عند حافة الحلبة. تسأل عن رقم النزال.", "quiz_d2_senaryo_jury_20": "يتلقّى الرياضي ضربة قوية ويبدأ أنفه بالنزيف بشدّة. أثناء فحص الطبيب، تُبلِغ مسؤول اللجنة القادم بالوضع.", "quiz_d2_senaryo_jury_21": "يتلقّى الرياضي ركلةً عاليةً أو ضربة كوعٍ دورانية قوية جداً على الرأس ويُسقَط. يدخل الطبيب الحلبة؛ تُبلِغ لجنة التحكيم بسبب الإصابة.", "quiz_d2_senaryo_jury_22": "بعد ضربةٍ منخفضة غير مقصودة يسقط المقاتل أرضاً بألمٍ شديد. أثناء انتظارك الطبيب، تُبلِغ المسؤولين التقنيين بموضع الإصابة بالضبط.", "quiz_d2_senaryo_jury_23": "يتلقّى مقاتل ضربة ركبة قوية على الأضلاع ولا يستطيع الوقوف مستقيماً. تُبلِغ لجنة التحكيم بالحالة.", "quiz_d2_senaryo_jury_24": "خلال اشتباكٍ عنيف أو بعد ضربة جسمٍ قوية يشعر الرياضي بالغثيان ويتقيّأ على أرضية الحلبة. تتوجّه إلى لجنة التحكيم وتُبلِغ بما حدث.", "quiz_d2_senaryo_jury_25": "يتلقّى الرياضي ضربة قاضية قوية ويفقد وعيه تماماً على الأرض. أثناء تدخّل الفريق الطبي، تُبلِغ لجنة التحكيم بالحالة.", "quiz_d2_senaryo_jury_26": "خلال جلسةٍ طويلة تبدأ بالشعور بالتوعّك وعليك مغادرة مهمتك للراحة قليلاً. تُعلِم لجنة التحكيم.", "quiz_d2_senaryo_jury_27": "عند حافة الحلبة تواجه مشكلة صحية مفاجئة وخطيرة وتحتاج إلى مساعدة طبية متخصّصة. تُعبّر عن حاجتك بوضوح.", "quiz_d2_senaryo_jury_28": "تشعر بالدوار وتواجه صعوبة في الوقوف. تُبلِغ بهذه الحالة الخاصة.", "quiz_d2_senaryo_jury_29": "أثناء فصلك بين الرياضيين شعرتَ بألمٍ حادٍّ في ذراعك ولا تستطيع متابعة المهمة. تُعلِم لجنة التحكيم.", "quiz_d2_senaryo_jury_30": "تشعر فجأةً بألمٍ شديد في المعدة وبالغثيان. تُعلِم لجنة التحكيم فوراً.", "quiz_d2_senaryo_jury_31": "تسبّب لك قدمك ألماً شديداً. تُبلِغ بذلك.", "quiz_d2_senaryo_jury_32": "تشعر بالضعف والارتجاف والتعرّق. تُبلِغ الطاولة بحالتك.", "quiz_d2_senaryo_jury_33": "تلاحظ أن ضغط دمك قد ارتفع وأن رأسك ينبض. تُبلِغ لجنة التحكيم بارتفاع ضغط دمك.", "quiz_d2_senaryo_jury_34": "تلاحظ أن ربطة عنقك (البابيون) قد انفكّت وفُقِدت. تطلب من زميل أو من لجنة التحكيم ربطةً بديلة.", "quiz_d2_senaryo_jury_35": "تلاحظ أن أرضية الحلبة تنفكّ عند الركن أو تُكوّن ثنياتٍ خطرة قد يتعثّر بها الرياضيون. تُبلِغ لجنة التحكيم.", "quiz_d2_senaryo_jury_36": "أثناء الاشتباك يستند الرياضيان إلى حبال الحلبة فترتخي الحبال بشكلٍ خطير. تُبلِغ لجنة التحكيم.", "quiz_d2_senaryo_jury_37": "قبل النزال القادم يوجد غبارٌ جافّ أو أوساخ صغيرة على أرضية الحلبة يجب مسحها. تطلب من المسؤولين التنظيف.", "quiz_d2_senaryo_jury_38": "انتشر نزيف أنف أحد الرياضيين على حبال الحلبة. تطلب من المسؤولين التنظيف.", "quiz_d2_senaryo_jury_39": "سكب المدرّبون كثيراً من الماء في الاستراحة وتشكّلت بركة ماء على الأرض تُزلِق الرياضيين. تطلب من المسؤولين التنظيف.", "quiz_d2_senaryo_equipment_1": "يأتي رياضي بقفازات غير معتمدة. تُبلِغه بقاعدة IFMA.", "quiz_d2_senaryo_equipment_2": "تفحص واقيات ساق الرياضي وترى أنها غير مقبولة. تطلب منه تبديلها.", "quiz_d2_senaryo_equipment_3": "تلاحظ أن قفازات الرياضي مرتخية وتدور. تخبره بما عليه فعله.", "quiz_d2_senaryo_equipment_4": "قميص الرياضي خارج البنطال. تطلب منه ترتيبه.", "quiz_d2_senaryo_equipment_5": "قبل بداية النزال وبعد التحية تعطي الرياضيين التعليمات.", "quiz_d2_senaryo_equipment_6": "قبل ارتداء القفازات عليك فحص اللفافات على يدي الرياضي.", "quiz_d2_senaryo_equipment_7": "تلاحظ أن الرياضي يرتدي واقي كاحل (جوارب) تحت واقي الساق، وهو ممنوع في هذه الفئة. تُبلِغ بذلك.", "quiz_d2_senaryo_equipment_8": "شعر الرياضي الطويل يخرج من واقي الرأس. تخبره بما عليه فعله.", "quiz_d2_senaryo_equipment_9": "وضع المدرّب كثيراً من الفازلين على وجه الرياضي. تطلب منه مسحه.", "quiz_d2_senaryo_equipment_10": "يأتي الرياضي بواقي أسنانٍ أحمر أو زهري، وهو ممنوع. تطلب منه تبديله.", "quiz_d2_senaryo_equipment_11": "تلاحظ أن الرياضي يضع مشبك شعر. تطلب منه إزالته.", "quiz_d2_senaryo_equipment_12": "يضع الرياضي واقي رأسه ويأتي إلى المنتصف لكنه نسي وضع واقي الأسنان. تعطيه تعليماً.", "quiz_d2_senaryo_equipment_13": "أثناء فحص المعدّات تسأل الرياضي إن كان يضع واقي العانة.", "quiz_d2_senaryo_equipment_14": "أثناء فحص المعدّات تسأل الرياضية إن كانت تضع واقي الصدر.", "quiz_d2_senaryo_equipment_15": "جاء الرياضي بحجابٍ أسود / بدلة جسم. تقول إنها غير مقبولة ويجب أن تكون بيضاء.", "quiz_d2_senaryo_equipment_16": "تفحص قدمي الرياضي وتلاحظ أن أظافر قدميه طويلة جداً. تطلب منه تقليمها.", "quiz_d2_senaryo_equipment_17": "تلاحظ أن المدرّب في الركن يرتدي صندلاً أو شبشباً. تُبلِغه بالقاعدة.", "quiz_d2_senaryo_equipment_18": "يرتدي المدرّب سترة ثقيلة أو ملابس غير رياضية. تطلب منه خلعها.", "quiz_d2_senaryo_equipment_19": "انتهى الوايكرو والنزال على وشك البدء. تخبر الركن أنهم يستطيعون وضع واقي الرأس.", "quiz_d2_senaryo_equipment_20": "انتهى النزال تماماً. تخبر المدرّب أنهم يستطيعون نزع واقي رأس الرياضي.", "quiz_d2_senaryo_equipment_21": "انتهى النزال لكن القرار الرسمي لم يُعلَن بعد. يحاول مدرّب نزع القفازات. توقِفه.", "quiz_d2_senaryo_equipment_22": "تبدأ الجولة وقد نسي المدرّب قنّينة الماء على أرضية الحلبة. تطلب منه أخذها.", "quiz_d2_senaryo_equipment_23": "خلال الاستراحة يسكب المدرّب كثيراً من الماء على الرياضي فيبلّل أرضية الحلبة. تنبّهه.", "quiz_d2_senaryo_equipment_24": "خلال الاستراحة تلاحظ أن واقي كوع الرياضي قد انزاح. تطلب من المدرّب تعديله.", "quiz_d2_senaryo_equipment_25": "خلال النزال تدور واقيات ساق الرياضي باستمرار. تطلب من الركن تثبيتها بالشريط اللاصق.", "quiz_d2_senaryo_equipment_26": "قبيل بدء الجولة ترك الركن منشفة معلّقة على حبال الحلبة. تطلب منهم إزالة المنشفة.", "quiz_d2_senaryo_equipment_27": "في الاستراحة يمدّ المدرّبون أيديهم بين حبال الحلبة إلى الداخل. تطلب منهم المدّ من فوق الحبال.", "quiz_d2_senaryo_judge_1": "اقترب أحد الإعلاميين من طاولة الحكّام الجانبيين أو وقف أمامها. تطلب منه التراجع.", "quiz_d2_senaryo_judge_2": "لم تبقَ بطاقات تنقيط على الطاولة. تُبلِغ لجنة التحكيم.", "quiz_d2_senaryo_judge_3": "لا تجد قلمك. تطلبه من لجنة التحكيم.", "quiz_d2_senaryo_judge_4": "هناك مشكلة تقنية في شاشة التنقيط، وتسأل لجنة التحكيم إن كان جهازك يستجيب. تُبلِغها بأنك ضغطت الزرّ.", "quiz_d2_senaryo_judge_5": "أثناء فحص الأجهزة تُبلِغ بأنك لم تضغط الزرّ.", "quiz_d2_senaryo_judge_6": "أثناء فحص الأجهزة ضغطتَ الزرّ الخطأ وتُبلِغ لجنة التحكيم بذلك.", "quiz_d2_senaryo_judge_7": "خلال النزال ضغطتَ زرّ إعادة الضبط بالخطأ. تُعلِم لجنة التحكيم.", "quiz_d2_senaryo_judge_8": "خلال النزال لا يعمل الجهاز لأن القابس/الكابل انفصل. تُعلِم لجنة التحكيم فوراً.", "quiz_d2_senaryo_judge_9": "خلال النزال أعطيتَ نقطة للركن الخطأ. تُبلِغ بذلك.", "quiz_d2_senaryo_judge_10": "بعد فحص النظام تسأل لجنة التحكيم إن كان جهازك يعمل. تُبلِغ بأن كل شيء على ما يرام.", "quiz_d2_senaryo_timekeeper_1": "خلال النزال تجمّد نظام Rsportz. تُعلِم لجنة التحكيم فوراً.", "quiz_d2_senaryo_timekeeper_2": "شغّلتَ موسيقى الوايكرو على الحاسوب لكن لا يخرج صوت من السمّاعات. تُبلِغ بالوضع.", "quiz_d2_senaryo_timekeeper_3": "أعطى الحكم أمر «الوقت» لتصحيح معدّة. تؤكّد أنك أوقفتَ الوقت الرسمي.", "quiz_d2_senaryo_timekeeper_4": "أعطى الحكم أمر «تشوك» (قاتل) لاستئناف النزال. تؤكّد أنك أعدتَ تشغيل الوقت.", "quiz_d2_senaryo_announcer_1": "تُعلِن أن على رياضيَي النزال القادم الاستعداد.", "quiz_d2_senaryo_announcer_2": "تنادي رياضي الركن الأحمر للنزال الثاني في الحلبة A إلى منطقة الحلبة فوراً.", "quiz_d2_senaryo_announcer_3": "لم يحضر أحد الرياضيين رغم النداءات. تُطلِق النداء الأخير قبل الفوز بالانسحاب.", "quiz_d2_senaryo_announcer_4": "وصلك القرار الرسمي. تُعلِن فوز الركن الأزرق.", "quiz_d2_senaryo_announcer_5": "قرّر المندوب التقني أخذ استراحة غداء رسمية. تُعلِن توقّف الجلسة.", "quiz_d2_senaryo_announcer_6": "تنتهي استراحة الدقيقة وتبدأ الجولة الجديدة قريباً. تطلب من المدرّبين مغادرة الحلبة.", "quiz_d2_senaryo_referee_1": "قبيل بداية الجولة الأولى تنادي الرياضيَين إلى المنتصف، تدعوهما إلى الاحترام المتبادل، تتمنّى لهما التوفيق وترسلهما إلى ركنيهما.", "quiz_d2_senaryo_referee_2": "يتجاهل الرياضي نفسه تنبيهك الأول ويكرّر المخالفة البسيطة. قبل إعطاء العقوبة توجّه تنبيهك الأخير.", "quiz_d2_senaryo_referee_3": "خلال الجولة يتحدّث مقاتل الركن الأزرق باستمرار بعدوانية لاستفزاز خصمه. تأمره بالتوقّف.", "quiz_d2_senaryo_referee_4": "يُسقِط الرياضي واقي أسنانه على أرضية الحلبة عمداً ليستريح. تعطيه تعليماً فوراً.", "quiz_d2_senaryo_referee_5": "يضع الرياضي قدماً لعرقلة الرياضي الآخر. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_6": "يُشبِك الرياضي ذراع خصمه من الأسفل ويضغط على رقبته (مسك الرقبة والذراع). تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_7": "خلال الاشتباك يضرب المقاتل بأعلى رأسه وجه/رأس خصمه. توقِف الحركة وتنبّه على المخالفة.", "quiz_d2_senaryo_referee_8": "يمسك الرياضي بحبال الحلبة بيده أثناء ضربة الركبة ليحافظ على توازنه. تعطيه أمراً.", "quiz_d2_senaryo_referee_9": "مباشرةً بعد أن أعلن الجرس نهاية الجولة وأعطيتَ أمر «يوت»، يوجّه الرياضي ضربة. تنبّهه على هذه المخالفة الخطيرة.", "quiz_d2_senaryo_referee_10": "يمسك المقاتل الأزرق ساق المقاتل الأحمر ويتقدّم 4 خطوات عبر الحلبة دون أي ضربة. توقِف الحركة وتنبّه.", "quiz_d2_senaryo_referee_11": "ضرب الرياضي الأحمر الرياضي الأزرق وهو على الأرض. أوقِف النزال، أرسِل الرياضي الأزرق إلى الركن الأبيض، نادِ الركن الأحمر إلى المنتصف وأعلِن العقوبة رسمياً بالتوجّه إلى لجنة التحكيم وكل حكمٍ جانبي.", "quiz_d2_senaryo_referee_12": "يبصق الرياضي بغضبٍ باتجاه خصمه أو الركن. توقِف النزال وتعطي عقوبة.", "quiz_d2_senaryo_referee_13": "في نزالٍ لفئةٍ عمرية أصغر تُمنَع فيها ضربات الرأس تماماً، يوجّه الرياضي ضربةً مباشرة إلى الوجه. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_14": "خلال الاشتباك يعضّ الرياضي كتف خصمه. توقِف النزال فوراً وتُعلِن العقوبة للمسؤولين.", "quiz_d2_senaryo_referee_15": "خلال الاشتباك يرفع الرياضي خصمه بالورك ويرميه على أرضية الحلبة. توقِفه وتسمّي المخالفة.", "quiz_d2_senaryo_referee_16": "ينزع الرياضي واقي رأسه دون إذن. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_17": "يطوّق المقاتل الأحمر خصر المقاتل الأزرق ويرفعه بالكامل في الهواء. تنبّه فوراً.", "quiz_d2_senaryo_referee_18": "لا يمسك الرياضي الحبال بيده لكنه يستمدّ قوة/سنداً من الحبال ليركل. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_19": "يسقط المقاتل الأزرق أرضاً ويُسقِط المقاتل الأحمر كامل وزنه عليه عمداً. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_20": "ينزلق الرياضي ويسقط، وتلمس ركبته الأرض، ومع ذلك يحاول توجيه ضربة من هذا الوضع. تخبره أن ذلك ممنوع.", "quiz_d2_senaryo_referee_21": "يكون الرياضي منهكاً جداً في الاشتباك ويُسقِط نفسه أرضاً عمداً للهروب من الحركة. تأمره بالوقوف والقتال.", "quiz_d2_senaryo_referee_22": "في موقفٍ سريع يضرب الرياضي عانة الرياضي الآخر عن غير قصد. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_23": "ترى بوضوح أن الرياضي يوجّه ركبةً مباشرة إلى عانة خصمه عمداً. توقِف النزال وتعطي عقوبة.", "quiz_d2_senaryo_referee_24": "يضرب الرياضي عمداً مؤخّرة رقبة خصمه في الاشتباك. تتوجّه إلى لجنة التحكيم وتُعلِن العقوبة.", "quiz_d2_senaryo_referee_25": "يمسك الركن الأحمر قفاز الركن الأزرق باستمرار لمنع ضرباته. تنبّه الركن الأحمر.", "quiz_d2_senaryo_referee_26": "لا يمتثل الرياضي لأوامر الحكم حتى بعد عدّة تنبيهات. توجّه التنبيه الأخير.", "quiz_d2_senaryo_referee_27": "في نزالٍ لفئةٍ عمرية أصغر تُمنَع فيها ضربات الرأس تماماً، يوجّه الرياضي للمرة الثالثة ضربةً مباشرة إلى الوجه. تعطيه عقوبة.", "quiz_d2_senaryo_referee_28": "في نزالٍ لفئةٍ عمرية أصغر تُمنَع فيها ضربات الرأس، يضع الرياضي ركبةً على رأس خصمه. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_29": "في نزال ناشئين تُمنَع فيه ضربات الكوع على الرأس، يضع الرياضي كوعاً في وجه خصمه. تعطيه تنبيهاً.", "quiz_d2_senaryo_referee_30": "نُبِّه الرياضي مراراً خلال النزال على أنواع مختلفة من المخالفات. على هذا السلوك غير الرياضي تعطي عقوبة.", "quiz_d2_senaryo_referee_31": "عددتَ للرياضي بعد سقوطه. هزّ الرياضي رأسه كأنه يشير إلى أنه لا يريد المتابعة. لتوضيح الموقف تسأل الرياضي:", "quiz_d2_senaryo_referee_32": "لم يأتِ الركن الأزرق إلى حافة الحلبة رغم أن الركن الأحمر جاهز. أي أمرٍ تعطيه لحكم التوقيت؟", "quiz_d2_senaryo_referee_33": "استمرّ النزال ثلاث جولات كاملة. وبناءً على ذلك، ما نتيجة النزال؟", "quiz_d2_senaryo_referee_34": "لا يستطيع الرياضي مجاراة خصمه ولا الدفاع عن نفسه. تعطي أمر «يوت» وتُنهي النزال بأي قرار:", "quiz_d2_senaryo_referee_35": "تلاحظ في منتصف النزال أن ذراع الرياضي قد خُلِعت. توقِف النزال بأمر «يوت»، وتعطي حكم التوقيت أمر «الوقت» وتنادي الطبيب. بأي قرارٍ تُنهي النزال؟", "quiz_d2_senaryo_referee_36": "سقط رياضي الركن الأزرق بسبب ضربة رأسٍ قوية. أرسلتَ خصمه إلى الركن الأبيض. إن رأيتَ أنه من غير المناسب أن يتابع الرياضي الأزرق، بأي قرارٍ تُنهي النزال:", "quiz_d2_senaryo_referee_37": "سقط رياضي الركن الأحمر بسبب ضربةٍ قوية على الأضلاع. أرسلتَ خصمه إلى الركن الأبيض. إن رأيتَ أنه من غير المناسب أن يتابع الرياضي الأحمر، بأي قرارٍ تُنهي النزال:", "quiz_d2_senaryo_referee_38": "سقط الركن الأزرق بعد ضربة رأسٍ قوية. بعد أن عددتَ حتى 8 أشار الرياضي إلى قدرته على المتابعة. مباشرةً بعد أمر «تشوك» سقط الرياضي مجدّداً فتابعتَ العدّ من 9. بأي قرارٍ تُنهي النزال:", "quiz_d2_senaryo_referee_39": "سقط الركن الأحمر بعد ضربةٍ قوية على الأضلاع. أرسلتَ الرياضي الأزرق إلى الركن الأبيض. في اللحظة التي تلاحظ فيها أن الرياضي الأحمر لا يستطيع التنفّس، توقِف العدّ وتنادي الطبيب. تُبلِغ لجنة التحكيم بنتيجة النزال:", "quiz_d2_senaryo_referee_40": "لحماية رياضيٍّ لم يقدّم أداءً جيداً في الجولة، بدأتَ العدّ في الوضع الصحيح. بعد 8 أشار الرياضي بوضوح إلى عدم رغبته في المتابعة. ما نتيجة النزال:", "quiz_d2_senaryo_referee_41": "رمى مدرّب رياضيٍّ لم يقدّم أداءً جيداً خلال النزال منشفةً داخل الحلبة. ما نتيجة النزال:", "quiz_d2_senaryo_referee_42": "لم يأتِ الركن الأحمر إلى حافة الحلبة رغم وصول الركن الأزرق. بأي قرارٍ يُعلَن الركن الخصم فائزاً بعد انقضاء مهلة الدقيقتين:", "quiz_d2_senaryo_referee_43": "أوقفتَ النزال بسبب رياضيٍّ ضرب خصماً ساقطاً على الأرض عمداً. قبضتَ يديك وعقدتَ ذراعيك أمامك للإشارة إلى نهاية النزال. ما نتيجة النزال:", "quiz_d2_senaryo_referee_44": "أوقفتَ النزال وناديتَ الطبيب لرياضيٍّ ينزف أنفه في منتصف النزال. أثناء فحص الطبيب السريع تسأل عن حالة الرياضي:", "quiz_d2_senaryo_referee_45": "للرياضي الذي لا يتوقّف نزيفه، ناديتَ الطبيب مجدّداً. تسأل الطبيب إن كان بالإمكان متابعة النزال:", "quiz_d2_senaryo_referee_46": "يريد الطبيب دخول الحلبة لفحص الرياضي. لكن في حالةٍ كنزيف الأنف لا يُسمح للطبيب بدخول الحلبة. تُنبّه إلى الوضع:", "quiz_d2_senaryo_referee_47": "خلال جولةٍ محتدمة وقف مدرّب الركن الأحمر وبدأ بالصراخ. أوقفتَ النزال ونبّهتَ المدرّب المخالف:", "quiz_d2_senaryo_referee_48": "ما ترتيب الأوامر عند السقوط (Knockdown)؟", "quiz_d2_senaryo_referee_49": "الرياضي الذي أرسلتَه إلى الركن الأبيض بعد سقوطه يقف مستنداً بذراعيه على الحبال في وضع استراحة. أي أمرٍ تعطيه:", "quiz_senaryo_1": "يفتقد أحد الرياضيين استمارة الإقرار الطبي الخاصة بـ IFMA.", "quiz_senaryo_2": "تطلب من الرياضي إظهار بطاقة الاعتماد.", "quiz_senaryo_3": "القائمة على الإنترنت غير مُحدَّثة.", "quiz_senaryo_4": "يأتي الرياضي إلى الوزن وهو يرتدي قلادة.", "quiz_senaryo_5": "يفتقد أحد الرياضيين نتيجة تحليل الدم HBV.", "quiz_senaryo_6": "لا تستطيع إدخال بيانات في القائمة.", "quiz_senaryo_7": "تذكر العدد الإجمالي للرياضيين الفائزين بالانسحاب.", "quiz_senaryo_8": "تقول إن على الرياضي الذهاب إلى الطبيب أولاً.", "quiz_senaryo_9": "يريد الرياضي خلع ملابسه الداخلية لتحقيق وزنٍ أقلّ في الميزان.", "quiz_senaryo_10": "تطلب من المدرّب الوثائق اللازمة للتسجيل.", "quiz_senaryo_11": "يأتي الرياضي إلى الوزن وهو يرتدي جوارب.", "quiz_senaryo_12": "تقول إن على الرياضي الصعود على الميزان بالملابس الداخلية فقط.", "quiz_senaryo_13": "يفتقد أحد الرياضيين نتيجة تحليل الدم HCV.", "quiz_senaryo_14": "تطلب من الرياضي الاستعداد للوزن.", "quiz_senaryo_15": "تُنبّه إلى أن الميزان يُظهِر قيمة أقلّ مقارنةً بميزان المراقبة.", "quiz_senaryo_16": "تطلب من الرياضي تسليم دفتر الرياضي (Athlete's Book).", "quiz_senaryo_17": "تطلب من الرياضيين إظهار جوازات سفرهم.", "quiz_senaryo_18": "يسأل مدرّب أو رياضي إن كان يستطيع استخدام الميزان للمراقبة. أجِب.", "quiz_senaryo_19": "جاء الرياضي إلى الوزن بأظافر قدمين طويلة.", "quiz_senaryo_20": "جاء الرياضي إلى الوزن بلحية وشارب. ماذا تقول؟", "quiz_senaryo_21": "في القائمة اسم الرياضي مكتوب بشكلٍ خاطئ.", "quiz_senaryo_22": "في القائمة بلد الرياضي خاطئ.", "quiz_senaryo_23": "تُنبّه إلى أن اسم الرياضي لا يظهر في القائمة.", "quiz_senaryo_24": "في القائمة جنس الرياضي خاطئ.", "quiz_senaryo_25": "تسأل عن البلد الذي يمثّله الرياضي.", "quiz_senaryo_26": "تنقص الرياضيَ تحاليل الدم. تطلب منه العودة بعد استكمال الوثائق.", "quiz_senaryo_27": "ستطلب تبديل الميزان.", "quiz_senaryo_28": "تذكر العدد الإجمالي للرياضيين المُستبعَدين.", "quiz_senaryo_29": "يأتي الرياضي إلى الوزن وهو يضع قُرطاً (بيرسينغ).", "quiz_senaryo_30": "تخبر الرياضي بأنه مُستبعَد بسبب الوزن.", "quiz_senaryo_31": "يأتي الرياضي إلى الوزن وهو يضع حلقاً.", "quiz_senaryo_32": "تطلب من الرياضي الموافقة الطبية.", "quiz_senaryo_33": "يجلس مدرّب على طاولة التسجيل. تُحيّيه وتسأله عن البلد الذي يمثّله.", "quiz_senaryo_34": "تقول إنه لا يُسمح إلا لرياضيٍّ واحد بدخول منطقة الوزن.", "quiz_senaryo_35": "تُنبّه إلى أن الميزان يُظهِر قيمة أعلى مقارنةً بميزان المراقبة.", "quiz_senaryo_36": "في القائمة فئة وزن الرياضي خاطئة.", "quiz_senaryo_37": "تفتقد إحدى الرياضيات إقرار عدم الحمل.", "quiz_senaryo_38": "تخبر الرياضي بأن عليه الصعود على الميزان.", "quiz_senaryo_39": "يفتقد أحد الرياضيين نتيجة تحليل الدم HIV.", "quiz_senaryo_40": "تقول إنه لا يُسمح للرياضي إلا بوزنٍ رسمي واحد.", "quiz_senaryo_41": "تواجه مشكلة إنترنت في جهازك.", "quiz_senaryo_42": "تطلب من مسؤول الوزن الإذن بالذهاب إلى الحمّام.", "quiz_senaryo_43": "الرياضي فوق حدّ الوزن.", "quiz_senaryo_44": "تُعلِن أن وزن السيدات قد بدأ.", "quiz_senaryo_45": "انتهى تسجيل الرياضي ووزنه. تُودّع الرياضي.", "quiz_senaryo_46": "تفتقد الرياضيَ موافقة مكافحة المنشّطات. ماذا تقول؟", "quiz_senaryo_47": "الرياضي تحت حدّ الوزن.", "quiz_senaryo_48": "الميزان لا يعمل.", "quiz_senaryo_49": "ستدخل غرفة الوزن وتطلب الإذن.", "quiz_senaryo_50": "ستنادي الرياضي التالي للوزن.", "quiz_senaryo_51": "لا يملك الرياضي موافقةً طبية.", "quiz_senaryo_52": "يأتي الرياضي إلى الوزن وهو يضع نظّارة.", "quiz_senaryo_53": "تذكر العدد الإجمالي للرياضيين الذين تمّ وزنهم.", "quiz_senaryo_54": "تُعلِن أن وزن الرجال قد بدأ.", "quiz_senaryo_55": "ستطلب من المسؤولين فحص الموازين."};

